@startuml

class FurnitureLine {
  + Name : string
}

class Furniture {
  + Reference : string
  + SellingPrice : double
}

class ComponentType {
  + Code : int
  + ManufacturingPrice : double
  + Type : string
}

class Store {
  + Address : string
  + FaxNumber : string
}

class Order {
  + OrderNumber : int
  + Date : date
}

class OrderLine {
  + Quantity : int
}

FurnitureLine "1" -- "*" Furniture : consists of
Furniture "*" -- "*" ComponentType : is composed of
Furniture "*" -- "*" OrderLine : is ordered in
OrderLine "*" -- "1" Order : part of
Order "*" -- "1" Store : placed by

@enduml

